// Verifies that toDxf({ excludeGenerated: true }) excludes entities and layers generated by setGenerated
// while keeping user content.
import assert from 'node:assert/strict';
import { readFile, mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { test } from 'node:test';
import * as esbuild from 'esbuild';
import { threeExamples, trustedTypes } from '../plugins.mjs';

async function loadCadEditor() {
	const outfile = path.join(await mkdtemp(path.join(tmpdir(), 'cad-editor-test-')), 'cad-editor-test.mjs');
	await esbuild.build({
		stdin: {
			contents: `
				export * from '@mlightcad/data-model';
				export { applyGenerated, dxfOut } from './src/generated.ts';
			`,
			resolveDir: process.cwd(),
		},
		outfile, bundle: true, format: 'esm', platform: 'node', logLevel: 'error',
		define: { define: 'undefined' },
		plugins: [trustedTypes, threeExamples],
	});
	return import(pathToFileURL(outfile).href);
}

test('toDxf with excludeGenerated excludes generated entities while keeping user lines', async () => {
	const { AcDbDatabase, AcDbFileType, AcDbLine, applyGenerated, dxfOut } = await loadCadEditor();
	const input = await readFile(new URL('./fixtures/dimensions.dxf', import.meta.url), 'utf8');
	const database = new AcDbDatabase();
	await database.read(input, { readOnly: false }, AcDbFileType.DXF);

	// Add a user line on layer '0'
	const userLine = new AcDbLine({ x: 1234, y: 5678, z: 0 }, { x: 4321, y: 8765, z: 0 });
	userLine.layer = '0';
	database.tables.blockTable.modelSpace.appendEntity(userLine);

	// Apply generated content (e.g. structural model beams and columns on locked layers)
	const generatedLayers = new Set(['S-BEAM', 'C-COLU', 'SAENGINE-PREVIEW']);
	const generatedDrawing = {
		layers: [
			{ name: 'S-BEAM', color: 3 },
			{ name: 'C-COLU', color: 4 },
		],
		entities: [
			{ kind: 'line', layer: 'S-BEAM', start: [9999, 8888], end: [7777, 6666] },
			{ kind: 'circle', layer: 'C-COLU', center: [5555, 4444], radius: 250 },
		],
	};
	const generatedIds = applyGenerated(database, new Set(), generatedDrawing);

	// Apply preview content
	const previewDrawing = {
		layers: [
			{ name: 'SAENGINE-PREVIEW', color: 2 },
		],
		entities: [
			{ kind: 'line', layer: 'SAENGINE-PREVIEW', start: [1111, 2222], end: [3333, 4444] },
		],
	};
	const previewIds = applyGenerated(database, new Set(), previewDrawing);

	// Export without excludeGenerated: includes both user and generated entities
	const fullDxf = dxfOut(database);
	assert.ok(fullDxf.includes('S-BEAM'), 'Full DXF should include generated layer S-BEAM');
	assert.ok(fullDxf.includes('SAENGINE-PREVIEW'), 'Full DXF should include preview layer SAENGINE-PREVIEW');
	assert.ok(fullDxf.includes('9999'), 'Full DXF should include generated entity coordinates');
	assert.ok(fullDxf.includes('1111'), 'Full DXF should include preview entity coordinates');
	assert.ok(fullDxf.includes('1234'), 'Full DXF should include user line coordinates');

	// Export with excludeGenerated: keeps user line, excludes generated and preview entities and layers
	const draftingDxf = dxfOut(database, {
		excludeGenerated: true,
		generated: generatedIds,
		preview: previewIds,
		generatedLayers,
	});

	assert.ok(draftingDxf.includes('1234'), 'Drafting DXF must keep user line start point');
	assert.ok(draftingDxf.includes('4321'), 'Drafting DXF must keep user line end point');
	assert.ok(!draftingDxf.includes('S-BEAM'), 'Drafting DXF must not include generated S-BEAM layer');
	assert.ok(!draftingDxf.includes('C-COLU'), 'Drafting DXF must not include generated C-COLU layer');
	assert.ok(!draftingDxf.includes('SAENGINE-PREVIEW'), 'Drafting DXF must not include preview layer');
	assert.ok(!draftingDxf.includes('9999'), 'Drafting DXF must not include generated line coordinates');
	assert.ok(!draftingDxf.includes('5555'), 'Drafting DXF must not include generated circle coordinates');
	assert.ok(!draftingDxf.includes('1111'), 'Drafting DXF must not include preview line coordinates');
});
